    adcs_vec3_t result_cmd;
    unint32 promote_mask = 0U;
    double d;
    double abs_d;
    size_t i;

    // 1. Input validation
    if ((requested_a_m2 == NULL) || (duty == NULL)) {
        duty->command = (adcs_vec3_t){0, 0, 0};
        duty->saturated_axes = 0U;
        return ADCS_E_NULL;
    }
    if ((!isfinite(full_scale_a_m2)) || (!isfinite(minimum_duty)) || 
        (full_scale_a_m2 <= 0.0) || (minimum_duty < 0.0) || (minimum_duty > 1.0)) {
        duty->command = (adcs_vec3_t){0, 0, 0};
        duty->saturated_axes = 0U;
        return ADCS_E_RANGE;
    }
    if (!adcs_is_finite_vec3(requested_a_m2)) {
        duty->command = (adcs_vec3_t){0, 0, 0};
        duty->saturated_axes = 0U;
        return ADCS_E_RANGE;
    }

    // 2. Process each axis
    for (i = 0; i < 3; ++i) {
        double val;
        double out_mag;

        switch (i) {
            case 0: val = requested_a_m2->x; break;
            case 1: val = requested_a_m2->y; break;
            case 2: val = requested_a_m2->z; break;
            default: val = 0.0; break;
        }

        // 3. Normalize
        d = val / full_scale_a_m2;
        abs_d = fabs(d);

        // 4. Decision table
        if (abs_d == 0.0) {
            out_mag = 0.0;
            // promote bit clear
        } else if (abs_d < minimum_duty) {
            out_mag = minimum_duty;
            // promote bit set
            promote_mask |= (unint32)(1U << i);
        } else if (abs_d <= 1.0) {
            out_mag = abs_d;
            // promote bit clear
        } else {
            out_mag = 1.0;
            // promote bit clear
        }

        // 5. Restore sign
        // Exact zero remains zero (avoids negative zero issues if strict equality matters)
        double pwm_val;
        if (val == 0.0) {
            pwm_val = 0.0;
        } else {
            pwm_val = copysign(out_mag, val);
        }

        switch (i) {
            case 0: result_cmd.x = pwm_val; break;
            case 1: result_cmd.y = pwm_val; break;
            case 2: result_cmd.z = pwm_val; break;
        }
    }

    // 6. Output assembly
    duty->command = result_cmd;
    duty->saturated_axes = promote_mask;

    // 7. Return success
    return ADCS_OK;
}

